changeSet.sql:
CREATE TABLE public.campaign ( id BIGSERIAL NOT NULL, name VARCHAR(200) NOT NULL, description TEXT, status VARCHAR(30) NOT NULL DEFAULT 'DRAFT', budget NUMERIC(15,2), currency VARCHAR(3) NOT NULL DEFAULT 'USD', start_at TIMESTAMPTZ, end_at TIMESTAMPTZ, created_by VARCHAR(100), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
CONSTRAINT pk_campaign PRIMARY KEY (id),
CONSTRAINT chk_campaign_status CHECK (status IN ('DRAFT','SCHEDULED','RUNNING','PAUSED','COMPLETED','CANCELLED')) );
CREATE INDEX idx_campaign_status ON public.campaign(status);
CREATE INDEX idx_campaign_dates ON public.campaign(start_at, end_at);
